        title: 'Where the budget goes',
        text: 'A two-kilometer single-mode link with four connector pairs and two splices at 1310 nanometers should lose roughly 0.7 decibels in the fiber, up to 3 in the connectors, and about 0.5 in the splices: around 4 decibels in all. A measured loss of 12 decibels on that link is not a long run; it is a bad event.',
